draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // Draw cave wall
  ctx.beginPath();
  ctx.moveTo(0, H / 2);
  ctx.lineTo(W, H / 2);
  ctx.stroke();

  // Draw prisoner
  ctx.beginPath();
  ctx.arc(W / 4, H / 2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 4, H / 2 + 20);
  ctx.lineTo(W / 4, H / 2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 4, H / 2 + 30);
  ctx.lineTo(W / 4 - 20, H / 2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 4, H / 2 + 30);
  ctx.lineTo(W / 4 + 20, H / 2 + 40);
  ctx.stroke();

  // Draw shadows
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(W / 2 + 50 * Math.sin(t), H / 2 - 20);
  ctx.lineTo(W / 2 + 50 * Math.sin(t), H / 2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 + 30 * Math.cos(t), H / 2 - 10);
  ctx.lineTo(W / 2 + 30 * Math.cos(t), H / 2 + 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 + 70 * Math.sin(t), H / 2 - 30);
  ctx.lineTo(W / 2 + 70 * Math.sin(t), H / 2 + 30);
  ctx.stroke();

  ctx.restore();
}
